CREATE FUNCTION public.assign_to_authorization(p_order uuid,p_kind text,p_label text,p_person uuid DEFAULT NULL,p_asset uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE o record; start_at timestamptz; cnt int;cap int; rid uuid;
BEGIN
IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;
SELECT t.*,COALESCE(l.timezone,'America/Chicago') tz INTO o FROM location_task_orders t JOIN project_locations l ON l.id=t.location_id WHERE t.id=p_order AND t.status='accepted';IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM location_to_terms WHERE task_order_id=p_order) THEN RAISE EXCEPTION 'Accepted structured task order required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(o.location_id::text,1));start_at:=(o.effective_date+COALESCE(o.effective_time,'00:00'::time)) AT TIME ZONE o.tz;
SELECT COALESCE(sum(qty_delta),0) INTO cap FROM location_task_order_lines WHERE task_order_id=p_order AND line_kind=p_kind AND lower(label)=lower(p_label);IF cap<=0 THEN SELECT authorized INTO cap FROM location_to_at(o.location_id,start_at) WHERE line_kind=p_kind AND lower(label)=lower(p_label);END IF;
IF p_kind='position' THEN IF p_person IS NULL OR NOT EXISTS(SELECT 1 FROM location_assignments WHERE location_id=o.location_id AND personnel_id=p_person AND status='active' AND assigned_at<=now() AND (unassigned_at IS NULL OR unassigned_at>now())) THEN RAISE EXCEPTION 'Person must be on this active location roster';END IF;
IF EXISTS(SELECT 1 FROM location_to_allocations a JOIN location_task_orders t ON t.id=a.task_order_id WHERE a.personnel_id=p_person AND t.location_id=o.location_id AND a.effective_until IS NULL AND a.task_order_id=p_order) THEN RAISE EXCEPTION 'Already allocated to this TO';END IF;
ELSE IF p_kind<>'asset' OR p_asset IS NULL OR NOT EXISTS(SELECT 1 FROM asset_assignments WHERE id=p_asset AND location_id=o.location_id AND status='active' AND start_at<=now() AND (end_at IS NULL OR end_at>now())) THEN RAISE EXCEPTION 'Asset must be assigned to this location';END IF;END IF;
SELECT count(*) INTO cnt FROM location_to_allocations WHERE task_order_id=p_order AND line_kind=p_kind AND lower(label)=lower(p_label) AND effective_until IS NULL;IF cap IS NULL OR cnt>=cap THEN RAISE EXCEPTION 'TO allocation exceeds authorized quantity';END IF;
UPDATE location_to_allocations a SET effective_until=start_at FROM location_task_orders t WHERE t.id=a.task_order_id AND t.location_id=o.location_id AND a.effective_until IS NULL AND ((p_person IS NOT NULL AND a.personnel_id=p_person) OR(p_asset IS NOT NULL AND a.asset_assignment_id=p_asset));
INSERT INTO location_to_allocations(task_order_id,line_kind,label,personnel_id,asset_assignment_id,effective_from,created_by) VALUES(p_order,p_kind,p_label,p_person,p_asset,start_at,auth.uid()) RETURNING id INTO rid;RETURN rid;
END $$;REVOKE ALL ON FUNCTION public.assign_to_authorization(uuid,text,text,uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.assign_to_authorization(uuid,text,text,uuid,uuid) TO authenticated;
CREATE FUNCTION public.complete_to_sheet(p_sheet uuid,p_person uuid,p_stay uuid,p_role text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s record;v record;cap int;cnt int;rid uuid;
BEGIN
IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;
SELECT sh.*,t.location_id,t.effective_date INTO s FROM location_to_sheets sh JOIN location_task_orders t ON t.id=sh.task_order_id WHERE sh.id=p_sheet AND t.status='accepted';IF NOT FOUND THEN RAISE EXCEPTION 'Accepted TO sheet required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_sheet::text,2));
SELECT vp.*,lv.location_id INTO v FROM visit_personnel vp JOIN location_visits lv ON lv.id=vp.visit_id WHERE vp.id=p_stay AND vp.personnel_id=p_person AND lv.location_id=s.location_id;IF NOT FOUND OR v.checked_out_at IS NULL OR NULLIF(v.signature_url,'') IS NULL OR v.signed_at IS NULL THEN RAISE EXCEPTION 'A signed completed location stay is required';END IF;
PERFORM _guard_punch_recount(p_stay,v.checked_in_at,v.checked_out_at);
SELECT COALESCE(sum((x->>'count')::int),0) INTO cap FROM jsonb_array_elements(s.required_counts) x WHERE lower(x->>'label')=lower(p_role);SELECT count(*) INTO cnt FROM location_to_sheet_entries WHERE sheet_id=p_sheet AND lower(role_label)=lower(p_role) AND voided_at IS NULL;IF cnt>=cap THEN RAISE EXCEPTION 'Sheet role count already fulfilled';END IF;
IF EXISTS(SELECT 1 FROM location_to_sheet_entries WHERE visit_personnel_id=p_stay AND voided_at IS NULL) THEN RAISE EXCEPTION 'This signed stay is already allocated to a MOBE/DEMOBE sheet';END IF;
INSERT INTO location_to_sheet_entries(sheet_id,personnel_id,role_label,in_at,out_at,signature_url,signed_at,created_by,visit_personnel_id) VALUES(p_sheet,p_person,p_role,v.checked_in_at,v.checked_out_at,v.signature_url,v.signed_at,auth.uid(),p_stay) RETURNING id INTO rid;
INSERT INTO audit_logs(user_id,user_email,action_type,resource_type,resource_id,changes_after) VALUES(auth.uid(),'to-sheet','to_sheet_signed_evidence','location_to_sheet_entries',rid,jsonb_build_object('sheet_id',p_sheet,'stay_id',p_stay));RETURN rid;
END $$;REVOKE ALL ON FUNCTION public.complete_to_sheet(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.complete_to_sheet(uuid,uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.guard_to_roster_capacity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE enabled boolean; limit_count int;current_count int;loc uuid;label_value text;
BEGIN
loc:=NEW.location_id;IF loc IS NULL THEN RETURN NEW;END IF;
SELECT EXISTS(SELECT 1 FROM location_task_orders t JOIN location_to_terms tm ON tm.task_order_id=t.id WHERE t.location_id=loc AND t.status='accepted' AND (t.effective_date+COALESCE(t.effective_time,'00:00'::time)) AT TIME ZONE COALESCE((SELECT timezone FROM project_locations WHERE id=loc),'America/Chicago')<=now()) INTO enabled;IF NOT enabled THEN RETURN NEW;END IF;PERFORM pg_advisory_xact_lock(hashtextextended(loc::text,1));
IF TG_TABLE_NAME='location_assignments' THEN
IF NEW.status<>'active' OR NEW.unassigned_at<=now() THEN RETURN NEW;END IF;IF TG_OP='UPDATE' AND OLD.location_id=NEW.location_id AND OLD.status='active' AND OLD.role_label IS NOT DISTINCT FROM NEW.role_label THEN RETURN NEW;END IF;
label_value:=COALESCE(NEW.role_label,'');SELECT COALESCE(authorized,0) INTO limit_count FROM location_to_at(loc,now()) WHERE line_kind='position' AND lower(label)=lower(label_value);SELECT count(*) INTO current_count FROM location_assignments WHERE location_id=loc AND id<>NEW.id AND status='active' AND assigned_at<=now() AND(unassigned_at IS NULL OR unassigned_at>now()) AND lower(COALESCE(role_label,''))=lower(label_value);
ELSE
IF NEW.status<>'active' OR NEW.end_at<=now() THEN RETURN NEW;END IF;IF TG_OP='UPDATE' AND OLD.location_id=NEW.location_id AND OLD.status='active' THEN RETURN NEW;END IF;SELECT type INTO label_value FROM assets WHERE id=NEW.asset_id;SELECT COALESCE(authorized,0) INTO limit_count FROM location_to_at(loc,now()) WHERE line_kind='asset' AND lower(label)=lower(label_value);SELECT count(*) INTO current_count FROM asset_assignments a JOIN assets x ON x.id=a.asset_id WHERE a.location_id=loc AND a.id<>NEW.id AND a.status='active' AND a.start_at<=now() AND(a.end_at IS NULL OR a.end_at>now()) AND lower(x.type)=lower(label_value);
END IF;
IF current_count>=COALESCE(limit_count,0) THEN RAISE EXCEPTION 'Demobilization required: location authorization for % is full or exceeded',label_value;END IF;RETURN NEW;
END $$;REVOKE ALL ON FUNCTION public.guard_to_roster_capacity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER to_roster_capacity BEFORE INSERT OR UPDATE ON public.location_assignments FOR EACH ROW EXECUTE FUNCTION public.guard_to_roster_capacity();CREATE TRIGGER to_asset_capacity BEFORE INSERT OR UPDATE ON public.asset_assignments FOR EACH ROW EXECUTE FUNCTION public.guard_to_roster_capacity();
CREATE FUNCTION public.guard_agency_provenance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM personnel_agency_provenance WHERE personnel_id=NEW.id AND (vendor_id IS DISTINCT FROM NEW.vendor_id OR NEW.employer_customer_id IS NOT NULL)) THEN RAISE EXCEPTION 'Agency signup ownership is permanent; employer change requires explicit reconciliation';END IF;RETURN NEW;END $$;REVOKE ALL ON FUNCTION public.guard_agency_provenance() FROM PUBLIC,anon,authenticated;CREATE TRIGGER agency_provenance_guard BEFORE UPDATE OF vendor_id,employer_customer_id ON public.personnel FOR EACH ROW EXECUTE FUNCTION public.guard_agency_provenance();
CREATE FUNCTION public.record_join_agency_provenance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE agency uuid;BEGIN IF NEW.status='approved' AND OLD.status IS DISTINCT FROM NEW.status THEN SELECT vendor_id INTO agency FROM project_join_tokens WHERE id=NEW.token_id;IF agency IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM personnel WHERE id=NEW.matched_personnel_id AND vendor_id=agency AND employer_customer_id IS NULL) THEN RAISE EXCEPTION 'Agency employer conflict: resolve worker ownership before approval';END IF;INSERT INTO personnel_agency_provenance(personnel_id,vendor_id,join_token_id,join_request_id) VALUES(NEW.matched_personnel_id,agency,NEW.token_id,NEW.id) ON CONFLICT(personnel_id) DO NOTHING;IF EXISTS(SELECT 1 FROM personnel_agency_provenance WHERE personnel_id=NEW.matched_personnel_id AND vendor_id<>agency) THEN RAISE EXCEPTION 'Worker belongs to a different signup agency';END IF;END IF;END IF;RETURN NEW;END $$;REVOKE ALL ON FUNCTION public.record_join_agency_provenance() FROM PUBLIC,anon,authenticated;CREATE TRIGGER join_agency_provenance BEFORE UPDATE OF status ON public.project_join_requests FOR EACH ROW EXECUTE FUNCTION public.record_join_agency_provenance();